__NUXT_JSONP__("/ru/how-to-apply/others", {data:[{details:{slug:"ru",pageTitle:"Другое | Mentor Language Institute",pageDescription:"Спасибо за Ваш интерес к MLI. Эта страница для тех у кого уже есть  не студенческая виза или кто из страны с ESTA или страны кто может подать на туристическую визу.",title:"Другое",image:"\u002Fimages\u002Fhow-to-apply\u002Fapply-others\u002Fapply-others.jpg",subtitle:["Спасибо за Ваш интерес к MLI.\u003Cbr \u002F\u003EЭта страница для тех у кого уже есть  не студенческая виза или кто из страны с ESTA или страны кто может подать на туристическую визу."],applyOnline:{imageLink:{image:"\u002Fimages\u002Fcommon\u002Fapply-now-ru.png",link:"\u002Fru\u002Fadmission"}},applicationSteps:{title:"Шаги подачи заявки",description:["Шаги подачи заявки зависят от страны заявителя, национальности, курса, визы и тд  \u003Cb\u003E Наши стаффы будут рады рассказать вам о шагах смены статуса на основе вашей индивидуальной заявки\u003C\u002Fb\u003E"]},needHelp:{title:"Нужна помощь? Спросите нас!",description:["- Могу ли я учиться в MLI без визы?\u003Cbr \u002F\u003E- Возможно ли подать заявку на обучение с другой визой не F1?\u003Cbr \u002F\u003E- Как долго я могу находиться в США без студенческой визы?\u003Cbr \u002F\u003E- Сколько часов в неделю мне нужно учиться в MLI чтобы поддерживать студенческий статус?","Ответы на эти вопросы вы сможете найти на сайте Консульства США или U.S. Citizenship and Immigration Services(USCIS).","Если вам нужно разъяснение перед подачей заявки, пожалуйста, свяжитесь с нами.","Наши сотрудники говорят на 8 разных языках."]},contactUs:{image:"\u002Fimages\u002Fcommon\u002Fcontact-us-ru.jpg",link:"\u002Fru\u002Fcontact",title:"Пожалуйста свяжитесь с нами.",lists:[{campus:"＜ВЕСТВУД КАМПУС＞",address:"10880 Вилшер Бул-р., Офис #122, Лос Анджелес, Калифорния 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜ГОЛЛИВУД КАМПУС＞",address:"7080 Голливуд Бул-р., Офис 314 Лос-Анджелес, Калифорния 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fothers",path:"\u002Fothers\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:30.017Z",updatedAt:"2025-05-26T12:06:27.834Z"}}],fetch:{},mutations:void 0});